def check(n):
    for k in range(n + 1):
        for m in range(n - k + 1):
            # Quadratic equation: 2x^2 + 2(k-m)x + (k+m + (k-m)^2 - 20) = 0
            a = 2
            b = 2 * (k - m)
            c = k + m + (k - m)**2 - 20

            discriminant = b**2 - 4*a*c
            if discriminant >= 0:
                x1 = (-b + discriminant**0.5) / (2*a)
                x2 = (-b - discriminant**0.5) / (2*a)
                for x in [x1, x2]:
                    if -1 < x < 1 and -1 < k - m + x < 1:
                        return True, (k, m, x)
    return False, None

for n in range(1, 31):
    possible, info = check(n)
    if possible:
        print(f"n={n} is possible with {info}")
        break
else:
    print("No solution found in n=1..30")
